<?php
declare(strict_types=1);namespace MiniErp\Platform;final class MultiTenantMigrationPlanner{
public function discover(string $directory):array{$out=[];foreach(glob(rtrim($directory,'/\\').'/*.sql')?:[] as $file){$sql=(string)file_get_contents($file);$risk=$this->risk($sql);preg_match('/^\s*--\s*(.+)$/m',$sql,$description);preg_match_all('/\b(?:TABLE(?:\s+IF\s+(?:NOT\s+)?EXISTS)?|INTO|FROM)\s+`?([a-z_][a-z0-9_]*)`?/i',$sql,$tables);$target=preg_match('/^202608(?:14|20)_/',basename($file))?'CONTROL_PLANE':'TENANT';$out[]=['id'=>basename($file),'path'=>$file,'checksum'=>hash_file('sha256',$file),'risk'=>$risk,'target'=>$target,'destructive'=>in_array($risk,['DESTRUCTIVE','MANUAL_REVIEW'],true),'description'=>$description[1]??'Migration oficial versionada','tables'=>array_values(array_unique($tables[1]??[])),'dependencies'=>[],'sql'=>$sql];}usort($out,fn($a,$b)=>strcmp($a['id'],$b['id']));return $out;}
public function risk(string $sql):string{if(preg_match('/\b(DROP\s+(?:TABLE|COLUMN|DATABASE)|DELETE\s+FROM|TRUNCATE)\b/i',$sql))return'DESTRUCTIVE';if(preg_match('/\b(DROP\s+INDEX|MODIFY\s+COLUMN|CHANGE\s+COLUMN)\b/i',$sql))return'MANUAL_REVIEW';if(preg_match('/\bALTER\s+TABLE\b/i',$sql))return'STRUCTURAL';return'SAFE_ADDITIVE';}
public function simulate(array $tenant,array $migration,array $history,bool $databaseExists,bool $shared):array{$status='PENDING';$reasons=[];if(!preg_match('/^mini_erp_tenant_[1-9][0-9]*$/',(string)($tenant['db_name']??'')))$reasons[]='DB_NAME_INVALID';if(!$databaseExists)$reasons[]='DATABASE_MISSING';if($shared)$reasons[]='DATABASE_SHARED';if(!in_array((string)($tenant['status']??''),['ativa','ativo'],true))$reasons[]='TENANT_INACTIVE';if(($migration['target']??'TENANT')!=='TENANT'){$status='BLOCKED';$reasons[]='TARGET_MISMATCH';}elseif(isset($history[$migration['id']]))$status=hash_equals((string)$history[$migration['id']],(string)$migration['checksum'])?'ALREADY_APPLIED':'CHECKSUM_MISMATCH';elseif($migration['destructive']){$status='BLOCKED';$reasons[]='MANUAL_APPROVAL_REQUIRED';}if($reasons!==[]&&$status==='PENDING')$status='BLOCKED';return['tenant_id'=>(int)$tenant['tenant_id'],'migration'=>$migration['id'],'status'=>$status,'reasons'=>$reasons,'risk'=>$migration['risk'],'write_performed'=>false];}}
